#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include <noarr/traversers.hpp>
#include <noarr/structures/interop/traverser_iter.hpp> // for range-based traverser iteration

// include common definitions
#include "defines.hpp"

// include benchmark-specific definitions
#include "symm.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// Layouts are chosen to improve spatial locality of the kernel:
	//  - C and B are stored with 'i' as the innermost (contiguous) dimension
	//    so that traversing over 'i' is cache-friendly.
	//  - A is stored with 'k' as the innermost dimension, matching the inner k-loop.
	//
	// C: i x j (M x N), physical order: j-major, i-contiguous
	DEFINE_PROTO_STRUCT(c_layout, i_vec ^ j_vec);
	// A: i x k (M x M), physical order: i-major, k-contiguous
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
	// B: i x j (M x N), physical order: j-major, i-contiguous
	DEFINE_PROTO_STRUCT(b_layout, i_vec ^ j_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	auto m = C | get_length<'i'>();
	auto n = C | get_length<'j'>();

	// Initialize C and B: for all i, j
	// Traversal order is layout-agnostic thanks to Noarr; we use a joint traverser
	// to get good spatial locality for both C and B.
	traverser(C, B).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);

		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
//
// Original mathematical kernel (PolyBench "symm"):
//
// for (i = 0; i < M; i++)
//   for (j = 0; j < N; j++) {
//     temp2 = 0;
//     for (k = 0; k < i; k++) {
//       C[k][j] += alpha * B[i][j] * A[i][k];
//       temp2   +=          B[k][j] * A[i][k];
//     }
//     C[i][j] = beta * C[i][j]
//               + alpha * B[i][j] * A[i][i]
//               + alpha * temp2;
//   }
//
// We keep this computation but:
//
//  - Change iteration order to "j outer, i inner".
//    This is safe because different columns j are independent.
//  - Parallelize over columns j with OpenMP (optional; ignored if not enabled).
//  - Choose layouts so that:
//      * traversing B and C over 'i' is contiguous (good cache use),
//      * traversing A over 'k' is contiguous.
//  - Hoist loop-invariant expressions outside inner loops
//    to reduce arithmetic operations.
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Traverser over (C, A, B); hoist 'j' to the top so that each outer
	// iteration corresponds to one full column j.
	auto main_trav = traverser(C, A, B).order(noarr::hoist<'j'>());

	#pragma scop
	// Parallelize across columns: each iteration of this loop processes
	// one full column j. Different columns never write to the same C[i][j],
	// so this is race-free.
	#pragma omp parallel for schedule(static)
	for (auto trav_j : main_trav) { // trav_j has 'j' fixed, remaining dims: 'i', 'k'
		// Loop over i (rows) for this column j
		trav_j.template for_dims<'i'>([&](auto trav_ij) {
			// trav_ij has 'j' and 'i' fixed, 'k' free

			// Extract current (i, j) indices once
			auto state_ij = trav_ij.state();
			const auto i_idx = get_index<'i'>(state_ij);
			const auto j_idx = get_index<'j'>(state_ij);

			// Load B[i][j] once and precompute alpha * B[i][j] to
			// avoid redundant multiplications in the inner k-loop.
			const num_t Bij       = B[state_ij];
			const num_t alpha_Bij = alpha * Bij;

			// Accumulator for the second sum
			num_t temp2 = 0;

			// Inner loop over k: 0 <= k < i
			// We use for_dims<'k'> and keep the triangular condition
			// as in the original algorithm.
			trav_ij.template for_dims<'k'>([&](auto trav_ijk) {
				auto state_ijk = trav_ijk.state();
				const auto k_idx = get_index<'k'>(state_ijk);

				if (k_idx < i_idx) {
					// Build states for accesses that differ from (i,j,k)
					//  - C[k][j]
					//  - B[k][j]
					//  - A[i][k]
					auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
					auto s_ik = idx<'i', 'k'>(i_idx, k_idx);

					const num_t Aik = A[s_ik];

					// C[k][j] += alpha * B[i][j] * A[i][k];
					C[s_kj] += alpha_Bij * Aik;

					// temp2   +=          B[k][j] * A[i][k];
					temp2   += B[s_kj] * Aik;
				}
			});

			// Final update of C[i][j]:
			// C[i][j] = beta * C[i][j]
			//           + alpha * B[i][j] * A[i][i]
			//           + alpha * temp2;
			auto s_ij = state_ij;
			auto s_ii = idx<'i', 'k'>(i_idx, i_idx);
			const num_t Aii = A[s_ii];

			C[s_ij] = beta      * C[s_ij]
			        + alpha_Bij * Aii
			        + alpha     * temp2;
		});
	}
	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
