		C[state] = (num_t)((i + j) % 100) / m;
		B[state] = (num_t)((n + i - j) % 100) / m;
	});

	// Initialize A as lower triangular, rest filled with -999
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);

		if (k <= i)
			A[state] = (num_t)((i + k) % 100) / m;
		else
			A[state] = (num_t)-999;
	});
}

// computation kernel
//
// Original mathematical intent (POLYBENCH SYMM):
//   C := beta * C + alpha * A * B
// where A is symmetric and only its lower triangle is stored.
// The algorithm exploits symmetry:
//   for i in 0..M-1
//     for j in 0..N-1
//       temp2 = 0
//       for k in 0..i-1
//         C[k][j] += alpha * B[i][j] * A[i][k]
//         temp2   +=         B[k][j] * A[i][k]
//       C[i][j] = beta * C[i][j] + alpha * B[i][j] * A[i][i] + alpha * temp2
//
// The implementation below preserves this computation but:
//   * Parallelizes across the independent 'j' (column) dimension with OpenMP.
//   * Uses a Noarr slice on 'k' to restrict k < i, removing an inner-branch.
//   * Hoists repeatedly used values (B[i][j], A[i][i]) into scalars.
//   * Keeps all loop nests expressed via Noarr traversers/ranges.
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Base traverser over all three bags; dimensions present:
	//   C: 'i', 'j'
	//   A: 'i', 'k'
	//   B: 'i', 'j'
	// so the combined traverser sees 'i', 'j', 'k'.
	auto base_trav = traverser(C, A, B);

	// We parallelize over the column dimension 'j'.
	// range<'j'>() returns an object whose iteration variable is a traverser
	// with 'j' fixed to a particular column. Different iterations (columns)
	// are independent, so this is safe for parallel execution.
	auto j_range = base_trav.template range<'j'>();

	// Parallel over columns. If OpenMP is not enabled, this pragma is ignored
	// and the code runs sequentially but still uses Noarr for traversal.
	#pragma omp parallel for schedule(static)
	for (auto trav_j : j_range) {
		// trav_j: traverser with current 'j' fixed; remaining dims: 'i', 'k'.

		// Loop over rows i for this column j.
		trav_j.template for_dims<'i'>([&](auto trav_ij) {
			// trav_ij: traverser with 'j' and 'i' fixed; remaining dim: 'k'.

			// State for (i, j) needed multiple times.
			auto state_ij = trav_ij.state();
			auto i_idx = get_index<'i'>(state_ij);
			auto j_idx = get_index<'j'>(state_ij);

			// Accumulator over k.
			num_t temp2 = 0;

			// B(i,j) is reused many times in the k-loop; hoist it.
			const num_t Bij = B[state_ij];

			// Restrict the inner k-loop to 0 <= k < i using a slice on 'k'.
			// This removes the inner `if (k < i)` branch from the original
			// code while preserving semantics.
			//
			// For i_idx == 0 the slice has zero length and the loop body
			// is skipped, as in the original k < i loop.
			trav_ij
				.order(slice<'k'>(0, i_idx))
				.for_each([&](auto state_ijk) {
					// state_ijk: state with i, j fixed and 0 <= k < i.
					auto k_idx = get_index<'k'>(state_ijk);

					// States for the required accesses at this (i,j,k):
					//   C[k][j], B[k][j], A[i][k]
					auto s_kj = idx<'i', 'j'>(k_idx, j_idx);
					auto s_ik = idx<'i', 'k'>(i_idx, k_idx);

					const num_t Aik = A[s_ik];

					// C[k][j] += alpha * B[i][j] * A[i][k]
					C[s_kj] += alpha * Bij * Aik;

					// temp2   +=         B[k][j] * A[i][k]
					temp2   += B[s_kj] * Aik;
				});

			// Final update of C[i][j]:
			//   C[i][j] = beta * C[i][j]
			//             + alpha * B[i][j] * A[i][i]
			//             + alpha * temp2
			const num_t Aii = A[idx<'i', 'k'>(i_idx, i_idx)];
			auto s_ij = state_ij;

			C[s_ij] = beta * C[s_ij]
			        + alpha * Bij * Aii
			        + alpha * temp2;
		});
	}
}

} // namespace

int main(int argc, char *argv[]) {
