// computation kernel
//
// Original mathematical kernel (Polybench SYMM):
//   for i
//     for j
//       temp2 = 0
//       for k < i
//         C[k][j] += alpha * B[i][j] * A[i][k];
//         temp2   +=          B[k][j] * A[i][k];
//       C[i][j] = beta * C[i][j]
//               + alpha * B[i][j] * A[i][i]
//               + alpha * temp2;
//
// Optimizations applied:
//   * Data layout tuning:
//       - C and B have 'i' as inner, contiguous dimension; we iterate k over 'i'.
//       - A has 'k' as inner, contiguous dimension; inner loop over k hits A[i][k] contiguously.
//   * Loop reordering:
//       - Outer traversal over j (columns), which is safe because columns are independent.
//   * Branch removal:
//       - Instead of looping over all k and testing k<i, we slice dim 'k' to [0, i) with noarr::slice.
//   * Arithmetic hoisting:
//       - Precompute B[i][j] and alpha * B[i][j] outside the k-loop.
//       - Load A[i][k] once per k into a register.
//   * Parallelization:
//       - Columns (dimension 'j') are independent, so we parallelize over them with OpenMP.
//         Each thread works on a distinct traverser with fixed 'j', avoiding data races.
//
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// Base traverser over (C, A, B); we hoist 'j' so that it becomes the
	// outermost dimension for iteration and for parallelization.
	auto trav_by_j = traverser(C, A, B).order(noarr::hoist<'j'>());

	#pragma scop

	// Parallelize over columns j.
	// Each iteration of this loop owns one fixed j and performs the full
	// triangular computation over i and k for that column.
	#pragma omp parallel for schedule(static)
	for (auto trav_j : trav_by_j) {
		// trav_j: traverser with 'j' fixed, remaining dims: 'i' and 'k'

		// Extract j index once, reuse inside.
		auto state_j = trav_j.state();
		const std::size_t j_idx = noarr::get_index<'j'>(state_j);

		// Loop over i (rows) for this column j.
		trav_j.template for_dims<'i'>([&](auto trav_ij) {
			// trav_ij: traverser with 'j' and 'i' fixed, remaining dim: 'k'
			auto state_ij = trav_ij.state();
			const std::size_t i_idx = noarr::get_index<'i'>(state_ij);

			// Accumulator corresponding to "temp2" in the original kernel.
			num_t temp2 = (num_t)0;

			// B[i][j] is invariant across k for this (i,j).
			const num_t B_ij = B[state_ij];
			const num_t alpha_B_ij = alpha * B_ij;

			// Inner loop over k restricted to k < i:
			//   We use a slice on dimension 'k' to avoid an explicit (k < i) branch.
			//
			//   - Original: for k in [0, M) if (k < i) { ... }
			//   - New:      for k in [0, i)             { ... }
			auto trav_ijk = trav_ij.order(noarr::slice<'k'>((std::size_t)0, i_idx));

			trav_ijk.for_each([&](auto state_ijk) {
				const std::size_t k_idx = noarr::get_index<'k'>(state_ijk);

				// States for the required accesses (all states are dynamic):
				//   C[k][j], B[k][j], A[i][k]
				//
				// We construct only what is necessary; the structures ignore
				// surplus dimensions if present.
				auto s_kj = noarr::idx<'i', 'j'>(k_idx, j_idx);     // (k, j)
				auto s_ik = noarr::idx<'i', 'k'>(i_idx, k_idx);     // (i, k)

				const num_t A_ik = A[s_ik];

				// C[k][j] += alpha * B[i][j] * A[i][k];
				C[s_kj] += alpha_B_ij * A_ik;

				// temp2 += B[k][j] * A[i][k];
				temp2   += B[s_kj] * A_ik;
			});

			// Final update of C[i][j]
			auto s_ij = state_ij; // (i, j)
			const num_t A_ii = A[noarr::idx<'i', 'k'>(i_idx, i_idx)];

			// C[i][j] = beta * C[i][j]
			//         + alpha * B[i][j] * A[i][i]
			//         + alpha * temp2;
			C[s_ij] = beta * C[s_ij]
				+ alpha_B_ij * A_ii
				+ alpha * temp2;
		});
	}

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t m = M;
	std::size_t n = N;

	// input data
	num_t alpha;
	num_t beta;

	// lengths for all dimensions
	auto set_lengths =
		noarr::set_length<'i'>(m)
		^ noarr::set_length<'j'>(n)
		^ noarr::set_length<'k'>(m);

	// data containers
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto B = noarr::bag(noarr::scalar<num_t>() ^ tuning.b_layout ^ set_lengths);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_symm(alpha, beta, C.get_ref(), A.get_ref(), B.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (to prevent dead-code elimination)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
