/*
 * Optimized computation kernel for SYMM
 *
 * Original mathematical operation (PolyBench SYMM):
 *
 *   for i in [0, M)
 *     for j in [0, N)
 *       temp2 = 0
 *       for k in [0, i)
 *         C[k][j] += alpha * B[i][j] * A[i][k];
 *         temp2   +=          B[k][j] * A[i][k];
 *       C[i][j] = beta * C[i][j]
 *               + alpha * B[i][j] * A[i][i]
 *               + alpha * temp2;
 *
 * A is symmetric and only its lower triangle is stored (we access A[i][k] with k <= i).
 *
 * The optimized version below preserves the exact result but:
 *   1. Separates the beta scaling: C <- beta * C (single pass, cache‑friendly).
 *   2. Rewrites the triple loop to exploit symmetry explicitly:
 *
 *      For each unordered pair (i, k) with k < i, the original kernel adds:
 *        - to C[k][j]: alpha * A[i][k] * B[i][j]
 *        - to C[i][j]: alpha * A[i][k] * B[k][j]
 *
 *      We accumulate these contributions directly using loops:
 *        for i
 *          for k < i
 *            for j
 *              C[k][j] += alpha * A[i][k] * B[i][j];
 *              C[i][j] += alpha * A[i][k] * B[k][j];
 *
 *      and separately handle the diagonal term:
 *        C[i][j] += alpha * A[i][i] * B[i][j];
 *
 *   3. Chooses loop order i -> k -> j to:
 *        - traverse rows of B and C contiguously along 'j'
 *        - keep A[i][k] in a register across the inner j-loop.
 *
 * All loops are expressed using Noarr traversers and for_dims, as required.
 */
[[gnu::flatten, gnu::noinline]]
void kernel_symm(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// --------------------------------------------------------------------
	// 1) Scale the whole C matrix: C <- beta * C
	//    This is equivalent to the original per-element scaling but done
	//    in a single streaming pass, which improves cache behavior.
	// --------------------------------------------------------------------
	traverser(C).for_each([=](auto state) {
		C[state] *= beta;
	});

	// --------------------------------------------------------------------
	// 2) Add symmetric product contributions.
	//
	// We iterate over i, then over k (0 <= k < i), and finally over j.
	// For each (i, k) pair:
	//   - Aik = A[i][k] is read once.
	//   - Inner loop over j walks rows C[k][j], C[i][j], B[i][j], B[k][j]
	//     contiguously along dimension 'j'.
	// --------------------------------------------------------------------
	#pragma scop
	traverser(C, A, B).template for_dims<'i'>([=](auto trav_i) {
		// trav_i: 'i' is fixed, 'j' and 'k' are still available (where present).

		auto state_i = trav_i.state();
		const std::size_t i_idx = get_index<'i'>(state_i);

		// ---- 2a) Diagonal contribution: A[i][i] * B[i][j] ----------------
		//
		// For fixed i:
		//   C[i][j] += alpha * A[i][i] * B[i][j]  for all j.
		//
		// We fetch A[i][i] once and reuse it across the whole row.
		const num_t Aii = A[noarr::idx<'i', 'k'>(i_idx, i_idx)];

		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// trav_ij has 'i' and 'j' fixed.
			C[trav_ij] += alpha * Aii * B[trav_ij];
		});

		// ---- 2b) Off-diagonal symmetric contributions --------------------
		//
		// For each k in [0, i):
		//   let Aik = A[i][k];
		//   for all j:
		//     C[k][j] += alpha * Aik * B[i][j];
		//     C[i][j] += alpha * Aik * B[k][j];
		//
		// We express the k-loop with for_dims<'k'> and restrict it to k < i.
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// trav_ik has 'i' and 'k' fixed.
			auto state_ik = trav_ik.state();
			const std::size_t k_idx = get_index<'k'>(state_ik);

			// Only use the lower triangular part: k < i.
			if (k_idx >= i_idx)
				return; // skip this k

			// A[i][k] is reused across the full inner j-loop
			const num_t Aik      = A[trav_ik];
			const num_t alphaAik = alpha * Aik;

			// For fixed (i, k), iterate over all j.
			trav_ik.template for_dims<'j'>([&](auto trav_ikj) {
				// trav_ikj has 'i', 'k' and 'j' fixed.
				auto state_ikj = trav_ikj.state();
				const std::size_t j_idx = get_index<'j'>(state_ikj);

				// Build states for rows k and i at column j.
				// C and B are laid out in dimensions 'i' x 'j'.
				const auto s_kj = noarr::idx<'i', 'j'>(k_idx, j_idx);
				const auto s_ij = noarr::idx<'i', 'j'>(i_idx, j_idx);

				const num_t Bij = B[s_ij]; // B[i][j]
				const num_t Bkj = B[s_kj]; // B[k][j]

				// Symmetric updates:
				C[s_kj] += alphaAik * Bij; // contributes to row k
				C[s_ij] += alphaAik * Bkj; // contributes to row i
			});
		});
	});
	#pragma endscop
}

